window.GKA.contentParts.push({ subject: "reading", grade: "g5", levels: [
  {"n":1,"name":"Precise vocabulary","skill":"Choose exact, vivid words","speed":0.9,"words":[["meticulous","A meticulous artist checks every line."],["reluctant","A reluctant volunteer."],["abundant","An abundant harvest."],["vivid","A vivid memory."],["subtle","A subtle hint."],["genuine","A genuine smile."],["hesitate","Do not hesitate."],["persevere","Persevere through trouble."],["flourish","Plants flourish in spring."],["diminish","The noise will diminish."],["elaborate","Please elaborate on your idea."],["scarce","Water is scarce in the desert."],["tedious","Sorting beads is tedious work."],["astonish","The magic trick will astonish you."],["brisk","A brisk walk in the cold."],["linger","The smell of bread lingered."],["thrive","Plants thrive in sunlight."],["dwindle","Our supplies began to dwindle."],["candid","Give me a candid opinion."],["resilient","A resilient person bounces back."]],"story":{"title":"The Mural","text":"Ms. Alvarez was meticulous. Before the class painted the mural on the cafeteria wall, she had us sketch it four times. Some students were reluctant; a wall seemed too big to get right. But her hints were subtle and her praise was genuine, so nobody wanted to hesitate for long. Over three weeks, the gray wall began to flourish with vivid color: a river, a market, the mountains behind our town. On the last day, as the noise of the cafeteria diminished into a hush, we stepped back. The mural was not perfect. It was abundant, which was better.","questions":[{"q":"What does 'meticulous' tell you about Ms. Alvarez?","o":["She is careful about details","She is impatient","She paints quickly"],"a":0},{"q":"Why were some students reluctant?","o":["The wall seemed too big to get right","They disliked painting","It was too cold"],"a":0},{"q":"What does 'abundant' mean in the last line?","o":["Full and plentiful","Empty","Perfect"],"a":0},{"q":"How did the cafeteria sound at the end?","o":["Quiet","Loud","Musical"],"a":0}]},"story2":{"title":"The Scarce Hour","text":"Time was scarce the week before the recital, and Jonah's practice had dwindled to a few tedious minutes a day. His teacher gave him candid advice: play one measure meticulously rather than the whole piece carelessly. He hesitated, then tried it. The results were subtle at first, then vivid. By Friday the piece flourished. He lingered after the recital, astonished at the applause, and wrote the advice on a card for his music stand.","questions":[{"q":"What does scarce mean?","o":["In short supply","Plentiful","Loud"],"a":0},{"q":"What was the teacher's advice?","o":["Play one measure meticulously","Practice longer","Skip the recital"],"a":0},{"q":"What does dwindled mean?","o":["Shrank","Grew","Stopped"],"a":0},{"q":"How did Jonah feel after the recital?","o":["Astonished","Bored","Angry"],"a":0}]}},
  {"n":3,"name":"Greek roots","skill":"Roots like graph, phon, bio, geo","speed":0.9,"words":[["biography","A biography tells a life story."],["photograph","Take a photograph."],["telescope","A telescope sees far."],["symphony","A symphony has many instruments."],["geology","Geology studies rocks."],["thermometer","Read the thermometer."],["autobiography","An autobiography is written by its subject."],["microphone","Speak into the microphone."],["chronology","A chronology lists events in order."],["democracy","In a democracy, people vote."],["telegraph","A telegraph sent messages over wires."],["phonics","Phonics links letters to sounds."],["biodegradable","A biodegradable bag breaks down."],["geometry","Geometry studies shapes."],["chronic","A chronic cough lasts a long time."],["automatic","An automatic door."],["microbe","A microbe is a tiny living thing."],["symmetry","A butterfly has symmetry."],["thermal","A thermal blanket keeps heat in."],["graphic","A graphic novel uses pictures."]],"story":{"title":"The Night Sky Club","text":"Our Night Sky Club meets on the roof of the library with a telescope the geology teacher lent us. Each week someone reads a short biography of an astronomer. Last week it was my turn, and I chose Caroline Herschel, who discovered comets in the 1700s. I used a microphone because the wind was loud. We keep a chronology of what we see, and a thermometer tells us when to wear gloves. The photographs we take are blurry, but the club decided, by democracy, that blurry stars still count.","questions":[{"q":"What does the root 'tele' mean in telescope?","o":["Far","Light","Star"],"a":0},{"q":"What is a biography?","o":["The story of a person's life","A list of stars","A kind of telescope"],"a":0},{"q":"Why did the narrator use a microphone?","o":["The wind was loud","The roof was big","It was a rule"],"a":0},{"q":"How did the club decide that blurry stars count?","o":["By voting","The teacher decided","By flipping a coin"],"a":0}]},"story2":{"title":"The Root Detectives","text":"Mr. Sato's class became root detectives. He wrote chronometer on the board. Chrono, said Amir, time, like chronology. Meter, said Lena, measure, like thermometer. So a chronometer measures time, they concluded. Next came biodegradable. Bio means life, and degrade means break down. By the end of the week, when a photograph of a geode appeared, nobody asked what geo meant. Earth, they said together, and went looking for the next word to dig up.","questions":[{"q":"What does chrono mean?","o":["Time","Heat","Earth"],"a":0},{"q":"What does a chronometer do?","o":["Measures time","Measures heat","Takes pictures"],"a":0},{"q":"What does bio mean?","o":["Life","Light","Sound"],"a":0},{"q":"What does geo mean?","o":["Earth","Water","Air"],"a":0}]}},
  {"n":5,"name":"Latin roots","skill":"Roots like port, dict, struct, rupt","speed":0.9,"words":[["transport","Ships transport cargo."],["portable","A portable radio."],["predict","Predict the weather."],["dictionary","Look it up in the dictionary."],["construct","Construct a bridge."],["structure","A strong structure."],["interrupt","Do not interrupt."],["erupt","Volcanoes erupt."],["inspect","Inspect the engine."],["spectator","A spectator watches."],["export","Farms export fruit abroad."],["contradict","The facts contradict his story."],["destruction","The storm caused destruction."],["disrupt","Do not disrupt the class."],["respect","Show respect for elders."],["inspection","The bridge passed inspection."],["visible","The moon is visible tonight."],["audible","The whisper was barely audible."],["manual","Read the manual."],["scribble","Do not scribble on the wall."]],"story":{"title":"Bridge Day","text":"On Bridge Day, each team had to construct a structure from spaghetti that could transport a toy car across a gap. Spectators crowded the gym. Our team used a portable ruler and a dictionary of engineering terms. We predicted our bridge would hold two cars. Then my cousin interrupted with a sneeze, the table shook, and the bridge did not erupt, exactly, but it did sag. The judges inspected it closely. It held one car. We did not win, but we learned that a structure must survive the unexpected, including sneezes.","questions":[{"q":"What does the root 'struct' mean?","o":["Build","Carry","Say"],"a":0},{"q":"What did the bridge have to do?","o":["Carry a toy car across a gap","Hold a book","Look pretty"],"a":0},{"q":"What shook the table?","o":["A sneeze","An earthquake","A spectator"],"a":0},{"q":"What did the team learn?","o":["Structures must survive the unexpected","Spaghetti is weak","Judges are strict"],"a":0}]},"story2":{"title":"The Portable Bridge","text":"For the engineering challenge, Priya's team had to construct a portable bridge that could transport a toy truck across a gap. Their first structure collapsed under inspection. A spectator, Priya's grandfather, predicted the problem: the support was too far apart. They reconstructed it with a triangle brace. The truck crossed. Later Priya wrote in her dictionary of roots: port means carry, struct means build, spect means look. Then she added a fourth entry: dict means say, and Grandpa says a lot.","questions":[{"q":"What root means carry?","o":["Port","Struct","Spect"],"a":0},{"q":"What fixed the bridge?","o":["A triangle brace","More glue","A shorter truck"],"a":0},{"q":"Who predicted the problem?","o":["Priya's grandfather","The teacher","The truck"],"a":0},{"q":"What does spect mean?","o":["Look","Carry","Build"],"a":0}]}},
  {"n":7,"name":"Prefixes inter-, sub-, super-, trans-","skill":"Between, under, above, across","speed":0.8,"words":[["international","An international team."],["interact","Interact with others."],["submarine","A submarine dives."],["subway","Take the subway."],["superhero","A superhero flies."],["supervise","Supervise the kids."],["transform","Transform the room."],["translate","Translate the sign."],["transfer","Transfer the money."],["interview","A job interview."],["internet","The internet connects computers."],["intersection","Stop at the intersection."],["subtitle","Read the subtitle."],["submerge","Submerge the sponge."],["supermarket","Shop at the supermarket."],["supersonic","A supersonic jet."],["transparent","Glass is transparent."],["transplant","Transplant the seedling."],["interfere","Do not interfere."],["subzero","Subzero temperatures."]],"story":{"title":"The International Fair","text":"For the international fair, our class had to transform the gym into a world tour. Lena's family came from Brazil and helped translate signs into Portuguese. We built a cardboard submarine for the Pacific booth and a subway map for the Tokyo one. Parents came to supervise, but mostly they wanted to interact with the food. I interviewed a visitor from Kenya who said the fair was the best way to transfer a little of her home into ours. By the end, our teacher called us superheroes of hospitality, which we decided to take as a compliment.","questions":[{"q":"What does the prefix 'trans' mean in transform?","o":["Across or change","Under","Above"],"a":0},{"q":"What did Lena's family help with?","o":["Translating signs into Portuguese","Building a submarine","Cooking"],"a":0},{"q":"What did the Kenyan visitor say?","o":["The fair transferred a bit of her home","The food was cold","The gym was small"],"a":0},{"q":"Which word means 'to watch over'?","o":["Supervise","Interact","Translate"],"a":0}]},"story2":{"title":"The Submarine Interview","text":"For the international science fair, Leila interviewed a submarine engineer. He explained how the sub could transform from a surface boat to a deep diver by transferring water into tanks. She asked how crews interact in such a small space. Carefully, he said. He supervised a team that translated instruments into three languages. Leila's report earned a superlative from the judge: superb. Prefixes, she noticed, were everywhere in his job: sub, inter, trans, super.","questions":[{"q":"What does sub mean in submarine?","o":["Under","Over","Between"],"a":0},{"q":"What does transfer mean?","o":["Move across","Stay","Build"],"a":0},{"q":"What does the prefix inter mean?","o":["Between","Above","Below"],"a":0},{"q":"What does super mean in superb?","o":["Above or beyond","Under","Again"],"a":0}]}},
  {"n":9,"name":"Suffixes -able, -ible, -ity","skill":"Able to be, and qualities","speed":0.8,"words":[["comfortable","A comfortable chair."],["reliable","A reliable friend."],["flexible","A flexible plan."],["visible","Clearly visible."],["responsible","A responsible pet owner."],["curiosity","Curiosity drives science."],["community","A caring community."],["ability","A rare ability."],["possibility","Every possibility."],["generosity","Her generosity surprised us."],["enjoyable","An enjoyable trip."],["breakable","The vase is breakable."],["washable","Washable paint."],["edible","Edible flowers."],["terrible","A terrible storm."],["sensible","A sensible plan."],["activity","A fun activity."],["identity","Protect your identity."],["creativity","Creativity means new ideas."],["popularity","The game's popularity grew."]],"story":{"title":"The Reliable Kid","text":"Everyone in our community knew Sam as the reliable kid. If he said he would feed your cat, the cat got fed. When the library needed a responsible volunteer to run the summer reading table, Sam was the obvious possibility. His curiosity made him good at it; he asked every kid what they liked and found a book to match. He was flexible when the schedule changed and comfortable talking to shy readers. By August, the sign-up sheet was so full it was barely visible under the names. The librarian said Sam's real ability was generosity with his attention.","questions":[{"q":"Why did people trust Sam?","o":["He always did what he promised","He was loud","He was the oldest"],"a":0},{"q":"What made Sam good at the reading table?","o":["His curiosity about what kids liked","His big voice","His own books"],"a":0},{"q":"What does 'flexible' mean here?","o":["Able to adapt to change","Able to bend","Weak"],"a":0},{"q":"What was Sam's real ability, according to the librarian?","o":["Generosity with his attention","Reading fast","Being on time"],"a":0}]},"story2":{"title":"The Flexible Plan","text":"The camping trip needed a reliable plan, but a flexible one, because the forecast was changeable. Tamsin listed what was possible, what was visible from the ridge, and who was responsible for the stove. Her curiosity about the stars was contagious, and the group's generosity meant nobody carried too much. When the storm came, the plan bent and did not break. Comfortable it was not. Memorable it was.","questions":[{"q":"Why did the plan need to be flexible?","o":["The forecast was changeable","The group was large","The stove was broken"],"a":0},{"q":"What does reliable mean?","o":["Dependable","Expensive","Fast"],"a":0},{"q":"What suffix turns curious into curiosity?","o":["-ity","-able","-ible"],"a":0},{"q":"What happened when the storm came?","o":["The plan bent but did not break","They went home","The tent flew away"],"a":0}]}},
  {"n":12,"name":"Figurative language","skill":"Personification, hyperbole, alliteration","speed":0.9,"words":[["personification","The wind whispered is personification."],["hyperbole","I waited forever is hyperbole."],["alliteration","Silly snakes slide is alliteration."],["onomatopoeia","Buzz and crash are onomatopoeia."],["imagery","Imagery paints a picture."],["exaggerate","Do not exaggerate."],["symbol","A dove is a symbol of peace."],["mood","The mood was tense."],["tone","A playful tone."],["rhythm","The poem has rhythm."],["simile","A simile uses like or as."],["metaphor","A metaphor says one thing is another."],["idiom","An idiom is not literal."],["pun","A pun plays on words."],["sensory","Sensory words appeal to the senses."],["vivid","Vivid writing paints a picture."],["sizzle","Bacon began to sizzle."],["murmur","The crowd gave a murmur."],["thunderous","Thunderous applause."],["gleam","The sword's gleam."]],"story":{"title":"The Kitchen Orchestra","text":"On Sunday mornings our kitchen wakes up before we do. The kettle whistles its one-note song, the pan sizzles and spits, and the toaster pops like a tiny drummer who is always late. Dad says he has made a million pancakes, which is hyperbole, though it feels true. My sister swears the syrup bottle sighs when it is almost empty. That is personification, and also a sign we need groceries. Butter bubbles, bacon crackles, bowls bang: the alliteration is accidental, but the rhythm is real. By the time we sit down, the mood in the room is as warm as the plates.","questions":[{"q":"Which is an example of personification?","o":["The kitchen wakes up before we do","A million pancakes","Butter bubbles"],"a":0},{"q":"Which words are onomatopoeia?","o":["Sizzles, pops, crackles","Sunday, morning, kitchen","Warm, plates, syrup"],"a":0},{"q":"Why is 'a million pancakes' hyperbole?","o":["It exaggerates to make a point","It is a lie","It is a recipe"],"a":0},{"q":"What is the mood at the end?","o":["Warm and happy","Tense","Sad"],"a":0}]},"story2":{"title":"The Storm Wrote a Poem","text":"The thunder grumbled like an old man who had been woken too early. That is personification, said Ms. Reyes, handing out umbrellas. The rain hit the roof with a rat-a-tat, onomatopoeia. It was raining a million buckets, Teo said, hyperbole. The wild wind whipped and whistled, alliteration. By the time the bus came, the class had written an entire poem out of a storm, and the mood had gone from gloomy to gleeful.","questions":[{"q":"Which is personification?","o":["Thunder grumbled like an old man","Rat-a-tat","A million buckets"],"a":0},{"q":"Which is onomatopoeia?","o":["Rat-a-tat","Wild wind whipped","Gloomy"],"a":0},{"q":"A million buckets is an example of","o":["Hyperbole","Alliteration","Symbol"],"a":0},{"q":"How did the mood change?","o":["From gloomy to gleeful","From happy to sad","It stayed the same"],"a":0}]}},
  {"n":15,"name":"Words with multiple meanings","skill":"Use context to choose the meaning","speed":0.8,"words":[["current","The river current; current events."],["novel","A novel idea; read a novel."],["match","Light a match; a tennis match."],["patient","A patient person; a doctor's patient."],["object","An object on the table; object to a plan."],["address","Your home address; address the crowd."],["present","A birthday present; present your work."],["scale","Scale a wall; a fish scale; a weighing scale."],["season","Season the soup; spring is a season."],["volume","Turn up the volume; a thick volume."],["bank","A river bank. A savings bank."],["bark","Tree bark. A dog's bark."],["fair","A county fair. A fair decision."],["light","A light bag. A bright light."],["ring","A gold ring. The bells ring."],["spring","Spring flowers. A metal spring."],["watch","Watch the show. A wrist watch."],["fly","Birds fly. A fly buzzed."],["pitch","Pitch the ball. A high pitch."],["row","Row the boat. A row of seats."]],"story":{"title":"The Current Problem","text":"The river's current was too strong for our model boat, so our science club had to address the problem. Jonah proposed a novel idea: add a keel shaped like the fish scale pattern he found in a thick volume on marine biology. Some members objected, but our teacher asked us to be patient and test it. On race day, we presented the new boat and it stayed as straight as a match flame. Current events, our teacher joked, are now in our favor. We won the match, and the object of the lesson was clear: read the context before you decide what a word, or a problem, means.","questions":[{"q":"In the first sentence, 'current' means","o":["The flow of water","Happening now","Electricity"],"a":0},{"q":"What does 'a novel idea' mean?","o":["A new idea","An idea from a book","A bad idea"],"a":0},{"q":"What does 'objected' mean?","o":["Disagreed","Picked up an item","Agreed"],"a":0},{"q":"Which 'volume' is a book?","o":["A thick volume on marine biology","Turn up the volume","The volume of water"],"a":0}]},"story2":{"title":"A Patient Patient","text":"Dr. Mendez had a patient who was very patient. The boy had broken his arm, and the novel she lent him was his only entertainment. He read it twice. Did you like it? she asked. He objected to the ending, he said, but the main object of the story was clear. She presented him with a second novel. For now, she said, the present is the best medicine. He agreed, which was a match for her mood, and they both laughed at how many meanings a single word can hold.","questions":[{"q":"In a patient who was very patient, the second patient means","o":["Calm and willing to wait","A sick person","A doctor"],"a":0},{"q":"What does novel mean here?","o":["A long story","New","A medicine"],"a":0},{"q":"Which word in the story is used with two meanings?","o":["Object","Doctor","Arm"],"a":0},{"q":"What does present mean in the present is the best medicine?","o":["A gift","Now","To show"],"a":0}]}},
  {"n":16,"name":"Connotation","skill":"Words with positive or negative feeling","speed":0.8,"words":[["thrifty","Thrifty means careful with money, in a good way."],["stingy","Stingy means unwilling to share."],["confident","A confident speaker."],["arrogant","An arrogant boast."],["curious","A curious student asks."],["nosy","A nosy neighbor pries."],["slender","A slender branch."],["scrawny","A scrawny kitten."],["unique","A unique design."],["weird","A weird noise."],["determined","A determined athlete keeps going."],["pushy","A pushy salesperson will not stop."],["youthful","A youthful energy."],["childish","Childish behavior is immature."],["aroma","The aroma of fresh bread."],["stench","The stench of garbage."],["cozy","A cozy cabin."],["cramped","A cramped closet."],["inquisitive","An inquisitive mind asks questions."],["meddling","A meddling neighbor interferes."]],"story":{"title":"Thrifty or Stingy?","text":"My grandfather saves rubber bands, washes plastic bags, and reuses birthday candles. My uncle calls him stingy. My mother calls him thrifty. Both words describe the same man, but one sounds like a complaint and the other like praise. When I asked Grandpa which he was, he laughed. He said he was confident, not arrogant, about one thing: he had never once run out of rubber bands. I used to think his habits were weird. Now I think they are unique. The words we choose, I realized, show how we feel as much as what we see.","questions":[{"q":"What is the difference between thrifty and stingy?","o":["Thrifty is positive, stingy is negative","They mean different things entirely","Stingy is a compliment"],"a":0},{"q":"How did the narrator's feelings change?","o":["From weird to unique","From unique to weird","They did not change"],"a":0},{"q":"What does the story say word choice shows?","o":["How we feel, not only what we see","How smart we are","Nothing"],"a":0},{"q":"What was Grandpa confident about?","o":["Never running out of rubber bands","Being rich","Winning arguments"],"a":0}]},"story2":{"title":"Confident or Arrogant?","text":"Two reporters covered the same spelling bee. One wrote that the champion was confident and unique, with a slender frame and an inquisitive stare. The other wrote that she was arrogant and weird, scrawny, with a nosy stare. Same facts. Different feelings. Ms. Flores asked the class which reporter liked the champion. Everyone pointed to the first. Connotation, she said, is the feeling a word carries in its pocket.","questions":[{"q":"Which word has a positive connotation?","o":["Confident","Arrogant","Scrawny"],"a":0},{"q":"Which word has a negative connotation?","o":["Nosy","Inquisitive","Unique"],"a":0},{"q":"Which reporter liked the champion?","o":["The first","The second","Neither"],"a":0},{"q":"What is connotation?","o":["The feeling a word carries","The spelling","The dictionary meaning"],"a":0}]}},
  {"n":17,"name":"Word relationships","skill":"Analogies and categories","speed":0.8,"words":[["analogy","Hot is to cold as up is to down."],["category","Fruit is a category."],["synonym","Big and large are synonyms."],["antonym","Hot and cold are antonyms."],["example","An apple is an example of fruit."],["relationship","The relationship between words."],["opposite","The opposite of fast."],["similar","Similar in meaning."],["specific","A specific word."],["general","A general word."],["part to whole","Petal to flower is part to whole."],["cause to effect","Rain to flood is cause to effect."],["item to category","Oak to tree is item to category."],["tool to user","Brush to painter is tool to user."],["degree","Warm to hot is a degree."],["function","A knife's function is to cut."],["homonym","Homonyms sound alike."],["root word","Help is the root word of helpful."],["compare","Compare the two."],["classify","Classify the words."]],"story":{"title":"The Analogy Game","text":"On bus rides, my brother and I play the analogy game. He says, bird is to nest as bee is to, and I say hive. The relationship is where something lives. Then we switch to categories: name three examples of tools, three specific kinds of weather, one general word for sofa, chair, and bed. He tried to trick me with synonyms and antonyms: glad is to happy as brave is to, and I said cowardly, but that is the opposite, an antonym, not a synonym. The right answer was courageous. Losing a round is no big deal. Similar to chess, the game is about seeing patterns.","questions":[{"q":"Bird is to nest as bee is to","o":["Hive","Honey","Flower"],"a":0},{"q":"What relationship does that analogy show?","o":["Where something lives","What something eats","Size"],"a":0},{"q":"Why was 'cowardly' wrong for 'brave'?","o":["It is an antonym, not a synonym","It is misspelled","It is a noun"],"a":0},{"q":"What general word covers sofa, chair, and bed?","o":["Furniture","Kitchen","Tools"],"a":0}]},"story2":{"title":"Hot Is to Cold","text":"The analogy game started simply. Hot is to cold as up is to? Down, said everyone. Antonyms. Then it got harder. Petal is to flower as? Page is to book: part to whole. Puppy is to dog as kitten is to? Cat: young to adult. Finally Mr. Ng gave one nobody could solve: question is to answer as problem is to? The room was silent until Ruby said, solution. He wrote it on the board as the specific example of a general idea: every relationship has a pattern.","questions":[{"q":"Hot is to cold is what kind of relationship?","o":["Antonyms","Synonyms","Part to whole"],"a":0},{"q":"Petal is to flower as page is to","o":["Book","Paper","Pen"],"a":0},{"q":"What completes question is to answer as problem is to?","o":["Solution","Trouble","Math"],"a":0},{"q":"What does every analogy have?","o":["A pattern of relationship","A rhyme","A picture"],"a":0}]}},
  {"n":19,"name":"Academic vocabulary 3","skill":"Words for analysis and argument","speed":0.9,"words":[["analyze","Analyze the data."],["interpret","Interpret the graph."],["justify","Justify your choice."],["significant","A significant change."],["relevant","Relevant evidence."],["perspective","A new perspective."],["assume","Do not assume."],["establish","Establish the facts."],["distinguish","Distinguish fact from opinion."],["emphasize","Emphasize the main point."],["evaluate","Evaluate the argument."],["summarize","Summarize the chapter."],["conclude","Conclude with a strong sentence."],["illustrate","Illustrate your claim with an example."],["prior","Prior knowledge helps."],["approach","Try a new approach."],["primary","A primary source is firsthand."],["secondary","A secondary source reports on others."],["acquire","Acquire new skills."],["consistent","Be consistent in your work."]],"story":{"title":"The Debate","text":"Our class debate topic was whether homework should be banned. To prepare, we had to analyze three articles and distinguish facts from opinions. My partner wanted to assume everyone hated homework, but I said we had to establish that with relevant evidence. We found a survey showing a significant number of students felt stressed, and we interpreted it carefully: stressed does not mean homework is useless. On debate day, we emphasized balance from a student's perspective and justified a limit of thirty minutes a night. The judges said our side was the most reasonable. We did not ban homework, but we changed the conversation.","questions":[{"q":"What was the debate about?","o":["Whether homework should be banned","School uniforms","Longer recess"],"a":0},{"q":"What did the narrator refuse to do?","o":["Assume without evidence","Read the articles","Speak"],"a":0},{"q":"What did the survey show?","o":["Many students felt stressed","Homework is useless","Teachers like homework"],"a":0},{"q":"What does 'justify' mean?","o":["Give good reasons for","Change","Ignore"],"a":0}]},"story2":{"title":"Interpreting the Chart","text":"The graph showed playground injuries by month. Dev assumed winter was most dangerous because of ice. Noor interpreted the data differently: the highest bar was in May. To justify her view she distinguished between slips on ice, which were rare, and falls from the climbing frame, which spiked in warm weather. The significant detail, she emphasized, was that more kids play outside in May. Dev conceded. A relevant fact, he said, beats a reasonable guess.","questions":[{"q":"What did Dev assume?","o":["Winter was most dangerous","May was most dangerous","Nobody got hurt"],"a":0},{"q":"What did the data actually show?","o":["The highest bar was in May","Ice caused most injuries","Injuries were equal"],"a":0},{"q":"What does justify mean?","o":["Give reasons for","Ignore","Draw"],"a":0},{"q":"What was the significant detail?","o":["More kids play outside in May","The frame was new","It snowed"],"a":0}]}},
  {"n":21,"name":"Text structure","skill":"Compare, sequence, problem and solution","speed":0.8,"words":[["sequence","Steps in sequence."],["chronological","In chronological order."],["compare","Compare the two."],["contrast","Contrast the colors."],["problem","State the problem."],["solution","Propose a solution."],["description","A detailed description."],["cause","The cause of the change."],["effect","The effect on the river."],["classify","Classify the rocks."],["first","First, gather supplies."],["finally","Finally, we arrived."],["similarly","Similarly, bees pollinate."],["in contrast","In contrast, owls hunt at night."],["as a result","As a result, the river rose."],["for instance","For instance, a whale is a mammal."],["one solution","One solution is to recycle."],["the problem","The problem is traffic."],["characteristics","Characteristics of a desert."],["steps","Follow the steps."]],"story":{"title":"Two Ways to Grow a Tomato","text":"Our class compared two ways to grow tomatoes: in soil and in water, a method called hydroponics. In chronological order, we planted seeds on March 1, saw sprouts by March 9, and measured weekly. The soil plants grew slower at first; in contrast, the water plants shot up fast. Then a problem appeared: the water plants drooped when the pump failed over a weekend. Our solution was a battery backup. By June, both groups had fruit. We classified them by size and found the soil tomatoes were smaller but sweeter. The cause, our teacher explained, was stress: a little struggle makes sweeter fruit.","questions":[{"q":"Which text structure organizes the dates?","o":["Chronological sequence","Problem and solution","Description"],"a":0},{"q":"What problem appeared?","o":["The pump failed","Birds ate the plants","The seeds did not sprout"],"a":0},{"q":"How did the two tomato groups compare at the end?","o":["Soil tomatoes were smaller but sweeter","Water tomatoes were sweeter","They were identical"],"a":0},{"q":"What was the cause of the sweeter fruit?","o":["A little stress","More water","Bigger pots"],"a":0}]},"story2":{"title":"Two Articles About Bees","text":"Rafael read two articles about bees. The first was chronological: it followed one bee from egg to forager in sequence. The second compared honeybees and bumblebees, then contrasted their hives. A third text he found online used problem and solution: fewer bees, so plant wildflowers. For his own report he chose cause and effect, because the question he cared about was why bees were disappearing in the first place. Structure, he learned, is a choice the writer makes to answer a question.","questions":[{"q":"What structure did the first article use?","o":["Chronological","Compare and contrast","Problem and solution"],"a":0},{"q":"What did the second article do?","o":["Compared and contrasted bees","Told a story","Listed steps"],"a":0},{"q":"Which structure did Rafael choose?","o":["Cause and effect","Description","Sequence"],"a":0},{"q":"Why does a writer choose a structure?","o":["To answer a question","To fill pages","By accident"],"a":0}]}},
  {"n":23,"name":"Words about emotion and motive","skill":"Why characters act","speed":0.8,"words":[["motive","The thief's motive."],["jealous","A jealous glance."],["grateful","Grateful for help."],["anxious","Anxious before the test."],["determined","Determined to finish."],["resentful","Resentful of the rule."],["sympathetic","A sympathetic listener."],["hesitant","A hesitant step."],["indifferent","Indifferent to the score."],["devoted","A devoted fan."],["envious","Envious of her new bike."],["remorseful","Remorseful after the fight."],["apprehensive","Apprehensive before the test."],["content","Content with a quiet evening."],["furious","Furious about the broken window."],["reluctant","Reluctant to try sushi."],["eager","Eager to start."],["ashamed","Ashamed of the lie."],["hopeful","Hopeful about the results."],["ambitious","An ambitious goal."]],"story":{"title":"Second Chair","text":"When Mira was moved from first chair to second in the school orchestra, she felt resentful. Her motive for practicing had been the solo, and now a new student, Theo, had it. For a week she was indifferent at rehearsal, playing just enough. Then she noticed Theo's hands shaking before every run-through; he was anxious, not arrogant. Something sympathetic stirred in her. She offered to practice the solo with him after school. Theo was hesitant, then grateful. By the concert, Mira was determined to make the whole section sound good, and she realized she had become devoted to the music instead of the chair.","questions":[{"q":"Why was Mira resentful at first?","o":["She lost the solo to Theo","She hated music","The teacher was unfair"],"a":0},{"q":"What changed her feelings?","o":["Noticing Theo was anxious","Getting the solo back","A new teacher"],"a":0},{"q":"What does 'indifferent' mean?","o":["Not caring","Very angry","Excited"],"a":0},{"q":"What was Mira devoted to by the end?","o":["The music","The first chair","Winning"],"a":0}]},"story2":{"title":"The Motive Behind the Mural","text":"When the mural was vandalized, everyone assumed the motive was jealousy, and all eyes turned to Kai, who had lost the design contest. Kai was anxious but determined to clear his name. He discovered the real reason: a resentful older student who thought the wall belonged to his class. Later, the principal was sympathetic to Kai and grateful for his honesty. Kai, indifferent to the praise, only asked if he could help repaint it.","questions":[{"q":"What motive did everyone assume?","o":["Jealousy","Boredom","Money"],"a":0},{"q":"Who really damaged the mural?","o":["A resentful older student","Kai","The principal"],"a":0},{"q":"What does indifferent mean?","o":["Not caring either way","Angry","Proud"],"a":0},{"q":"How did the principal feel toward Kai?","o":["Sympathetic and grateful","Suspicious","Annoyed"],"a":0}]}},
  {"n":25,"name":"Poetry words","skill":"Stanza, rhyme, meter, imagery","speed":0.8,"words":[["stanza","A poem's stanza."],["rhyme","Cat rhymes with hat."],["rhythm","Tap the rhythm."],["verse","A short verse."],["imagery","Strong imagery."],["repetition","Repetition adds power."],["metaphor","A bold metaphor."],["simile","A simile uses like."],["theme","The poem's theme."],["speaker","The poem's speaker."],["couplet","A couplet is two rhyming lines."],["haiku","A haiku has three lines."],["free verse","Free verse has no rhyme."],["line break","A line break ends a line."],["sonnet","A sonnet has fourteen lines."],["refrain","The refrain repeats."],["mood","The mood is calm."],["alliteration","Alliteration repeats sounds."],["onomatopoeia","Buzz is onomatopoeia."],["personification","The wind sang: personification."]],"story":{"title":"Writing the Lighthouse Poem","text":"Our assignment was a poem with two stanzas about a place we loved. I chose the lighthouse at Cape Ferris. In the first stanza, I used imagery: salt wind, a lamp like a slow heartbeat, gulls stitching the sky. That last part was a metaphor, and I was proud of it. The second stanza used repetition, the line 'still here' three times, because the lighthouse has survived two hundred storms. I did not force every line to rhyme; my teacher said rhythm matters more than rhyme. The speaker in my poem is not me exactly. It is someone who waits at the window. The theme, I think, is that steady things deserve to be loved.","questions":[{"q":"What is 'gulls stitching the sky'?","o":["A metaphor","A simile","A rhyme"],"a":0},{"q":"Why did the writer repeat 'still here'?","o":["The lighthouse survived many storms","To fill space","The teacher required it"],"a":0},{"q":"What did the teacher say matters more than rhyme?","o":["Rhythm","Length","Title"],"a":0},{"q":"What is the poem's theme?","o":["Steady things deserve love","Storms are dangerous","Gulls are noisy"],"a":0}]},"story2":{"title":"Reading the Poem Aloud","text":"The poem had three stanzas and a rhythm like a heartbeat. In the first, the speaker described a lighthouse, with the imagery of a steady eye. The second repeated the line, and still it turns, a repetition that built suspense. The third stanza revealed the theme: being steady for someone else. Nina read it aloud twice. The second time she heard the rhyme scheme she had missed and realized the speaker was not the poet, but the lighthouse itself.","questions":[{"q":"How many stanzas does the poem have?","o":["Three","Two","Five"],"a":0},{"q":"What is the repeated line an example of?","o":["Repetition","Simile","Rhyme"],"a":0},{"q":"What is the theme?","o":["Being steady for someone else","The sea is cold","Birds fly"],"a":0},{"q":"Who is the speaker of the poem?","o":["The lighthouse","Nina","A sailor"],"a":0}]}},
  {"n":27,"name":"Mythology and legend words","skill":"Words from old stories","speed":0.7,"words":[["myth","A Greek myth."],["legend","A local legend."],["hero","The hero returns."],["quest","A long quest."],["fate","Accept your fate."],["immortal","The gods were immortal."],["oracle","The oracle spoke."],["labyrinth","Lost in the labyrinth."],["titan","A mighty titan."],["trident","Poseidon's trident."],["mortal","A mortal can die."],["prophecy","The prophecy came true."],["sacrifice","A sacrifice for the gods."],["monster","A monster guarded the gate."],["temple","A marble temple."],["chariot","A golden chariot."],["nymph","A nymph of the forest."],["underworld","The underworld lies below."],["Olympus","Mount Olympus was home to the gods."],["epic","An epic tells a hero's long journey."]],"story":{"title":"The Corn Maze Quest","text":"Every October, the farm outside town builds a corn labyrinth, and the local legend says no one finds the center before sunset. My friends and I treated it like a hero's quest. We named Tomas our oracle, because he had studied the map from the fair poster, and he predicted three left turns. A scarecrow with a pitchfork looked like a titan holding a trident. Twice we hit dead ends, which felt like fate. But heroes in myths never quit at the second wall. At the center stood a bell, and we rang it at 5:40, twenty minutes before sunset. We are not immortal, but for one afternoon we were legends.","questions":[{"q":"What was the legend about the maze?","o":["No one finds the center before sunset","It is haunted","It has no center"],"a":0},{"q":"Why was Tomas called the oracle?","o":["He studied the map and predicted turns","He was the oldest","He could see over the corn"],"a":0},{"q":"What did the scarecrow resemble?","o":["A titan with a trident","A hero","A king"],"a":0},{"q":"What kept the friends going after dead ends?","o":["Heroes in myths do not quit","A reward","Their parents"],"a":0}]},"story2":{"title":"The Oracle in the Library","text":"The sixth-grade play told the myth of a hero on a quest through a labyrinth. Theo, playing the hero, kept forgetting his lines about fate. Backstage, the librarian, who everyone called the oracle, gave him a trick: say it to the trident, not the crowd. He did. On opening night, when the titan stepped out and the immortal queen spoke, Theo did not freeze. The legend of that performance, the kids joked, would outlive them all.","questions":[{"q":"What is a labyrinth?","o":["A maze","A ship","A mountain"],"a":0},{"q":"Who was called the oracle?","o":["The librarian","Theo","The queen"],"a":0},{"q":"What does immortal mean?","o":["Living forever","Very strong","Brave"],"a":0},{"q":"What is a quest?","o":["A long search or journey","A question","A costume"],"a":0}]}},
  {"n":29,"name":"History and civics words","skill":"Words from social studies","speed":0.7,"words":[["colony","A colony far from home."],["revolution","A revolution changes everything."],["constitution","The constitution is the highest law."],["independence","Independence Day."],["ancestor","My ancestor sailed here."],["immigrant","An immigrant builds a new life."],["economy","A strong economy."],["industry","The steel industry."],["representative","Elect a representative."],["liberty","Liberty for all."],["amendment","An amendment changes the constitution."],["citizen","A citizen has rights and duties."],["democracy","In a democracy, people vote."],["pioneer","A pioneer settled the frontier."],["treaty","A treaty ends a war."],["territory","The territory became a state."],["invention","The invention changed farming."],["frontier","The frontier was unexplored land."],["monument","A monument honors heroes."],["election","Vote in the election."]],"story":{"title":"Great-Grandmother's Suitcase","text":"In our attic is a suitcase that belonged to my great-grandmother, an immigrant who arrived in 1921 with one dress and a sewing machine. She found work in the garment industry, and later her shop helped the neighborhood economy. My ancestor never saw the constitution of her new country as just paper; she read it aloud to her children, especially the part about liberty. She voted in every election for her representative, even when her English was shaky. Independence, she wrote in a letter we still have, is not something you are given. It is something you practice.","questions":[{"q":"What did the great-grandmother bring?","o":["One dress and a sewing machine","A suitcase of money","Nothing"],"a":0},{"q":"What industry did she work in?","o":["Garment (clothing)","Steel","Farming"],"a":0},{"q":"What did she do with the constitution?","o":["Read it aloud to her children","Framed it","Ignored it"],"a":0},{"q":"What did she say about independence?","o":["It is something you practice","It is given to you","It is a holiday"],"a":0}]},"story2":{"title":"The Classroom Constitution","text":"Room 12 decided to write a constitution. First they held a revolution against the old rule that only the teacher chose the music. Then each representative, one per table, proposed a right. Independence to choose seats on Fridays passed easily. A rule about the class economy, trading pencils for library time, took a week of debate. In the end, they signed it, hung it by the door, and added a line about liberty: every voice gets a turn.","questions":[{"q":"What was the old rule they overturned?","o":["Only the teacher chose the music","No talking","No seats"],"a":0},{"q":"Who proposed the rights?","o":["A representative from each table","The principal","The parents"],"a":0},{"q":"What took a week to debate?","o":["The class economy rule","Seats","Music"],"a":0},{"q":"What does liberty mean?","o":["Freedom","Money","Silence"],"a":0}]}},
  {"n":32,"name":"Science and technology words","skill":"Words from science class","speed":0.7,"words":[["hypothesis","Form a hypothesis."],["variable","Change one variable."],["procedure","Follow the procedure."],["observation","Record each observation."],["conclusion","State the conclusion."],["organism","A tiny organism."],["ecosystem","A pond ecosystem."],["adaptation","A clever adaptation."],["technology","New technology."],["engineer","An engineer designs bridges."],["data","Record the data."],["evidence","Evidence supports a claim."],["model","A model represents a system."],["prototype","Test the prototype."],["circuit","Close the circuit."],["gravity","Gravity pulls down."],["habitat","A frog's habitat is a pond."],["microscope","Look through the microscope."],["molecule","A water molecule."],["renewable","Solar is renewable energy."]],"story":{"title":"The Pond Project","text":"Our hypothesis was that the school pond had more organisms near the reeds than in open water. The procedure was simple: scoop one jar from each spot, same time, same depth, so the only variable was location. Our observations surprised us. The reed jar swarmed with tiny life; the open jar held two water fleas and a leaf. We concluded that plants provide shelter, an adaptation that many organisms depend on. An engineer from the city visited and explained how technology like underwater cameras helps scientists study ecosystems without disturbing them. Next spring, we are building a floating reed island.","questions":[{"q":"What was the only variable in the experiment?","o":["Location","Time","Depth"],"a":0},{"q":"What did the reed jar show?","o":["Many organisms","Nothing","Only leaves"],"a":0},{"q":"What conclusion did the class reach?","o":["Plants provide shelter for organisms","Open water is best","Ponds are empty"],"a":0},{"q":"What are they building next?","o":["A floating reed island","A bridge","A camera"],"a":0}]},"story2":{"title":"The Variable Nobody Controlled","text":"The hypothesis was simple: bean plants grow faster with music. Group A played songs; Group B kept silence. The procedure was the same, the observation was daily, and the conclusion, after two weeks, favored music. Then Malik noticed the variable nobody had controlled. Group A's window faced south. The ecosystem on that sill was warmer and brighter. The engineer in him sighed. They repeated the experiment with both groups on the same shelf. Result: no difference. The organisms, it turned out, did not care about the playlist.","questions":[{"q":"What was the hypothesis?","o":["Plants grow faster with music","Plants need water","Beans dislike noise"],"a":0},{"q":"What variable was not controlled?","o":["Sunlight from the window","Water","Soil"],"a":0},{"q":"What was the final result?","o":["No difference","Music won","Silence won"],"a":0},{"q":"Why repeat the experiment?","o":["To control the uncontrolled variable","For fun","To grow more beans"],"a":0}]}},
  {"n":37,"name":"Words about money and work","skill":"Practical vocabulary","speed":0.7,"words":[["budget","Make a budget."],["expense","A big expense."],["income","Monthly income."],["profit","A small profit."],["invest","Invest in a tool."],["customer","A happy customer."],["schedule","Keep a schedule."],["cooperate","Cooperate with your partner."],["negotiate","Negotiate a price."],["responsibility","A big responsibility."],["salary","A monthly salary."],["savings","Put money in savings."],["loan","Borrow with a loan."],["interest","The bank pays interest."],["receipt","Keep the receipt."],["inventory","Count the inventory."],["deadline","Meet the deadline."],["teamwork","Teamwork makes it easier."],["supplier","The supplier sends lemons."],["advertise","Advertise the sale."]],"story":{"title":"The Lemonade Ledger","text":"This summer, my cousin and I ran a lemonade stand like a real business. We made a budget: lemons, sugar, cups, and a sign were our expenses, about twelve dollars. We decided to invest in a cooler so the ice would last. Our schedule was Saturdays from ten to two. The first week, income was nine dollars, so no profit. We negotiated with the bakery next door to sell their cookies for a share, and customers started coming for both. By August we had a forty-dollar profit and a lesson in responsibility: when you cooperate, everybody's stand does better.","questions":[{"q":"What were the expenses?","o":["Lemons, sugar, cups, and a sign","A cooler only","Cookies"],"a":0},{"q":"Why was there no profit the first week?","o":["Income was less than expenses","They forgot the sugar","It rained"],"a":0},{"q":"What deal did they negotiate?","o":["Selling the bakery's cookies for a share","Free lemons","A bigger table"],"a":0},{"q":"What is the lesson?","o":["Cooperation helps everyone","Lemonade is expensive","Never invest"],"a":0}]},"story2":{"title":"The Dog-Walking Company","text":"Three friends started a dog-walking company. Their income came from four customers at five dollars a walk. Their expenses were leashes, treats, and a sign. The budget balanced only after they learned to negotiate with the pet store for a discount. Their schedule put each walker on different days so nobody missed soccer. Profit after a month: forty-one dollars. They invested half in a wagon for a tired bulldog and agreed that responsibility, not the money, was the hard part.","questions":[{"q":"What was their income from?","o":["Four customers at five dollars a walk","A lemonade stand","Their parents"],"a":0},{"q":"What did they negotiate?","o":["A discount at the pet store","A longer summer","More customers"],"a":0},{"q":"What did they do with half the profit?","o":["Bought a wagon","Bought candy","Saved all of it"],"a":0},{"q":"What was the hard part?","o":["Responsibility","Counting money","Walking"],"a":0}]}},
  {"n":39,"name":"Argument and evidence","skill":"Claims, reasons, counterclaims","speed":0.7,"words":[["claim","State your claim."],["counterclaim","Address the counterclaim."],["evidence","Cite evidence."],["reasoning","Explain your reasoning."],["credible","A credible source."],["bias","Watch for bias."],["logical","A logical step."],["persuasive","A persuasive letter."],["conclude","Conclude strongly."],["refute","Refute the argument."],["source","Check the source."],["fact","A fact can be proven."],["opinion","An opinion is a belief."],["support","Support your claim."],["valid","A valid argument makes sense."],["relevant","Use relevant evidence."],["assert","Assert your point clearly."],["acknowledge","Acknowledge the other side."],["convince","Convince the reader."],["fallacy","A fallacy is faulty reasoning."]],"story":{"title":"Should Recess Be Longer?","text":"My claim is that recess should be twenty minutes longer. My reasoning: students focus better after moving, and I have evidence. A credible study from a university found that children who had more recess made fewer errors on afternoon tests. A counterclaim says longer recess means less learning time. I would refute that: fifteen minutes of distracted learning is worth less than ten minutes of focused learning. I know I have a bias, since I like recess, so I also asked teachers. Four of five agreed. It is logical to conclude that a longer recess is not a break from learning. It is part of it.","questions":[{"q":"What is the counterclaim?","o":["Longer recess means less learning time","Recess is dangerous","Kids dislike recess"],"a":0},{"q":"What makes the study credible?","o":["It came from a university","It was short","The writer liked it"],"a":0},{"q":"Why did the writer mention bias?","o":["To be honest that they like recess","To attack teachers","To end the essay"],"a":0},{"q":"How does the writer refute the counterclaim?","o":["Focused learning beats distracted learning","By ignoring it","By asking parents"],"a":0}]},"story2":{"title":"Should Homework Be Banned?","text":"Ana's claim was that homework should be banned. Her evidence was a survey of her own class, which she admitted was not fully credible because of bias: who would vote for more homework? Jun's counterclaim was that practice improves memory, and he cited a study of two thousand students. Ana refuted part of it: the study measured math, not reading. In the end, the logical conclusion both accepted was narrower than either claim: less homework, better designed. Persuasive, said the teacher, is not the same as right, and both of you were persuasive.","questions":[{"q":"What was Ana's claim?","o":["Homework should be banned","Homework should double","Reading is hard"],"a":0},{"q":"Why was her evidence weak?","o":["Bias in her own class survey","It was too old","It was about math"],"a":0},{"q":"What was Jun's counterclaim?","o":["Practice improves memory","Homework is fun","Teachers need it"],"a":0},{"q":"What conclusion did both accept?","o":["Less homework, better designed","No homework","More homework"],"a":0}]}},
  {"n":41,"name":"Commonly confused words","skill":"Accept or except, affect or effect","speed":0.7,"words":[["accept","Accept the gift."],["except","Everyone except me."],["affect","Rain can affect the game."],["effect","The effect of rain."],["than","Taller than me."],["then","Then we left."],["lose","Do not lose it."],["loose","A loose tooth."],["principal","The school principal."],["principle","A guiding principle."],["its","The dog wagged its tail."],["it's","It's raining."],["your","Your book."],["you're","You're late."],["whose","Whose coat is this?"],["who's","Who's coming?"],["desert","A sandy desert."],["dessert","Ice cream for dessert."],["weather","Sunny weather."],["whether","I wonder whether it will rain."]],"story":{"title":"The Principal's Principle","text":"Our principal has one principle: everyone plays. On field day, every student competes in something, except those who are sick, and even they keep score. Last year a loose shoelace made me lose the relay. I was sure the effect would be teasing, but the principal's rule had affected the whole school's attitude. Rather than laugh, my classmates said, better luck next time, and then invited me to the tug of war. I learned to accept that losing a race hurts less than you think, and that a good rule can matter more than a fast time.","questions":[{"q":"What is the principal's principle?","o":["Everyone plays","Winning matters most","No shoelaces"],"a":0},{"q":"Which sentence uses 'lose' correctly?","o":["A loose shoelace made me lose the relay","A lose shoelace made me loose","I will loose the race"],"a":0},{"q":"What was the effect of the rule on the school?","o":["A kinder attitude","More teasing","Fewer races"],"a":0},{"q":"What did the narrator accept?","o":["Losing hurts less than you think","Never running again","Teasing"],"a":0}]},"story2":{"title":"Accept the Effect","text":"Every student except Mia accepted the challenge to write a paragraph without a single confused word. Then the teacher read Mia's aloud: The weather will affect the race, whether we like it or not. Its start is at noon; it's going to be hot. Whose shoes are loose? Not mine, they're tighter than yours. The principal has one principle: no one loses on purpose. Perfect, said the teacher. Mia, who had only hesitated, took her seat. Then she accepted the effect of all that practice: a very long round of applause.","questions":[{"q":"Which sentence uses affect correctly?","o":["The weather will affect the race","The weather will effect the race","Both"],"a":0},{"q":"What is the difference between accept and except?","o":["Accept means receive; except means leaving out","They mean the same","Except is a verb"],"a":0},{"q":"Which word means a rule you live by?","o":["Principle","Principal","Lose"],"a":0},{"q":"Which is correct?","o":["Whose shoes are loose","Who's shoes are lose","Whose shoes are lose"],"a":0}]}},
  {"n":49,"name":"Reading a longer text","skill":"Theme, inference, and author's craft","speed":0.6,"words":[["theme","The story's theme."],["inference","Draw an inference."],["foreshadow","The storm clouds foreshadow trouble."],["flashback","A flashback to childhood."],["climax","The story's climax."],["resolution","The resolution ties it up."],["symbolism","Symbolism in the red door."],["irony","Irony surprises us."],["suspense","Suspense builds."],["narrator","An unreliable narrator."],["protagonist","The protagonist drives the story."],["antagonist","The antagonist opposes the hero."],["setting","The setting shapes the mood."],["point of view","First-person point of view uses I."],["plot twist","A plot twist surprises readers."],["rising action","Tension builds in the rising action."],["conflict","Conflict drives the plot."],["motif","A repeated motif of birds."],["dialogue","Dialogue reveals character."],["allusion","An allusion refers to another work."]],"story":{"title":"The Last Tree on Harlow Street","text":"When the city announced it would widen Harlow Street, the plan called for removing the old sycamore at the corner. To most people it was just a tree. To Dani, it was the place her father had taught her to climb, a memory that returned in flashback every time she passed it.\n\nShe started with a petition. Thirty signatures became three hundred. Then she did something riskier: she researched the tree's age. The county arborist confirmed it was over a century old, older than the street itself. That fact, more than any speech, changed the mood at the city meeting. A council member who had argued for the road admitted, with some irony, that his own grandfather had planted trees on Harlow Street in 1920.\n\nThe suspense ended at 9:14 p.m. with a vote of five to two. The road would curve. The sycamore would stay. Dani walked home under its branches, which had seemed, all week, to lean a little closer to the ground, as if listening. She knew that was imagination. She also knew that sometimes the oldest thing on the block is the one worth bending a road for.","questions":[{"q":"What is the theme of the story?","o":["Protecting what matters takes evidence and persistence","Roads are more important than trees","Petitions never work"],"a":0},{"q":"What fact changed the mood at the meeting?","o":["The tree was over a century old","Dani cried","The road cost too much"],"a":0},{"q":"What is the irony in the council member's admission?","o":["He argued against trees but his grandfather planted them","He was late","He liked Dani"],"a":0},{"q":"What is the climax?","o":["The vote","The petition","The flashback"],"a":0},{"q":"What might the branches 'leaning closer' symbolize?","o":["The tree's connection to the people who saved it","Wind","Danger"],"a":0}]},"story2":{"title":"The Clock Tower Letter","text":"Nobody in Pell's Crossing had climbed the clock tower in thirty years, not since the stairs were declared unsafe. That was why Esme noticed the light. It flickered at the top window every Thursday at nine, and it flickered in a pattern: three short, three long, three short. In the library she found that it was a distress signal, and in an old newspaper she found that the last clock keeper had vanished in 1994. Her friend Caleb said ghosts. Esme said evidence. On the fourth Thursday they borrowed a flashlight and climbed the stairs, which were old but not unsafe, only forgotten. At the top was no ghost. There was Mr. Abadi, the retired keeper, eighty-one years old, who had been climbing up every week to wind the clock because nobody else remembered how. The signal was not distress at all. It was the only pattern of blinks he knew, and he had hoped, for years, that someone would notice. Esme learned the winding sequence that night. The next Thursday, two lights flickered.","questions":[{"q":"What first caught Esme's attention?","o":["A light flickering at the top window","A noise","A letter"],"a":0},{"q":"What did the pattern of blinks turn out to be?","o":["The only pattern Mr. Abadi knew, a call for someone to notice","A real distress call","A ghost's message"],"a":0},{"q":"What is the climax of the story?","o":["Climbing the tower and finding Mr. Abadi","Reading the newspaper","Borrowing a flashlight"],"a":0},{"q":"Which clue foreshadowed the ending?","o":["The last keeper vanished in 1994","Caleb said ghosts","The library closed"],"a":0},{"q":"What does the final sentence suggest?","o":["Esme will keep winding the clock with him","The tower fell down","The lights went out"],"a":0}]}}
] });
